1	// Shared probe library for black-box observation of /workspace/dataset/test3_executable
2	import { execFile, execFileSync } from 'node:child_process';
3	export const EXE = '/workspace/dataset/test3_executable';
4	export const CONC = 48;
5	
6	/** Run once, synchronously. Returns {rc, out, err, lines} */
7	export function runSync(domain, strict = 'True') {
8	  try {
9	    const out = execFileSync(EXE, ['--domain', domain, '--strict', strict],
10	      { encoding: 'utf8', maxBuffer: 1 << 26 });
11	    return { rc: 0, out, err: '', lines: out.split('\n') };
12	  } catch (e) {
13	    return { rc: e.status ?? 1, out: e.stdout ?? '', err: e.stderr ?? '', lines: (e.stdout ?? '').split('\n') };
14	  }
15	}
16	
17	/** Run many domains in parallel. items: string[] (domains). Returns array of {rc,out,err,lines}. */
18	export async function runMany(domains, strict = 'True', conc = CONC) {
19	  const res = new Array(domains.length);
20	  let next = 0;
21	  const worker = async () => {
22	    for (;;) {
23	      const i = next++;
24	      if (i >= domains.length) return;
25	      res[i] = await new Promise(r => execFile(EXE, ['--domain', domains[i], '--strict', strict],
26	        { encoding: 'utf8', maxBuffer: 1 << 26 },
27	        (e, so, se) => r({ rc: e ? (e.code ?? 1) : 0, out: so, err: se, lines: so.split('\n') })));
28	    }
29	  };
30	  await Promise.all(Array.from({ length: Math.min(conc, domains.length) }, worker));
31	  return res;
32	}
