36	/** Compact a sorted list of [lo,hi] or ints into range pairs */
37	export function toRanges(sortedInts) {
38	  const out = [];
39	  for (const v of sortedInts) {
40	    const last = out[out.length - 1];
41	    if (last && last[1] === v - 1) last[1] = v; else out.push([v, v]);
42	  }
43	  return out;
44	}
